-- RepoShelf: check that every Supabase migration has been applied.
--
-- Paste into the Supabase SQL editor and run. It is read-only (a single SELECT), so it is safe to run at any time.
-- One row per migration file, in the order they are applied:
--   applied = true   every object that migration creates is present (tables, functions, columns, policies,
--                    indexes, constraints, triggers, seed rows and the key safety settings).
--   applied = false  something is missing; the `missing` column lists exactly what, and which file to re-run.
-- The last row summarises everything. Migrations are written to be re-run safely, so a false row can be fixed
-- by running that file again in the SQL editor (in order, and re-run 202610060019_merge_accounts.sql after
-- 202610160035_boards.sql).
--
-- Notes: seed-row checks (editorial shelves) show false if an administrator deleted one of those shelves on
-- purpose. Checks look at the end state, so a later migration that replaces a function is what a row verifies.
-- Extend this file whenever a migration is added.

with
 fns  as (select array_agg(distinct proname::text) a from pg_proc where pronamespace='public'::regnamespace),
 tbls as (select array_agg(relname::text) a from pg_class where relnamespace='public'::regnamespace and relkind in ('r','p')),
 cols as (select array_agg(table_name||'.'||column_name) a from information_schema.columns where table_schema='public'),
 pols as (select array_agg(policyname::text) a from pg_policies where schemaname='public'),
 idxs as (select array_agg(indexname::text) a from pg_indexes where schemaname='public'),
 cons as (select conname::text, pg_get_constraintdef(oid) def from pg_constraint where connamespace='public'::regnamespace),
 -- one row per check: the problem text when the check fails, null when it passes
 checks(ord, migration, problem, kind) as (values
  (1,'202610030001_accounts_editorial_analytics', nullif(array_to_string(array(select x from unnest(array['analytics_daily','analytics_events','analytics_limits','analytics_sessions','analytics_visitors','editorial_ribbons','editorial_settings','reposhelf_admins','user_likes']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (1,'202610030001_accounts_editorial_analytics', nullif(array_to_string(array(select x from unnest(array['reposhelf_analytics','reposhelf_delete_ribbon','reposhelf_ingest_events','reposhelf_is_admin','reposhelf_reorder_ribbons','reposhelf_save_ribbon','reposhelf_set_editorial','reposhelf_set_like']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (1,'202610030001_accounts_editorial_analytics', nullif(array_to_string(array(select x from unnest(array['analytics_admin','analytics_events_admin','likes_owner','ribbons_admin_insert','ribbons_public_anon','ribbons_read_members','settings_admin_update','settings_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (1,'202610030001_accounts_editorial_analytics', nullif(array_to_string(array(select x from unnest(array['analytics_time']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (2,'202610030002_admin_user_management', nullif(array_to_string(array(select x from unnest(array['admin_role_changes']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (2,'202610030002_admin_user_management', nullif(array_to_string(array(select x from unnest(array['reposhelf_list_users','reposhelf_set_admin']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (2,'202610030002_admin_user_management', nullif(array_to_string(array(select x from unnest(array['role_audit_admin']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (3,'202610030003_unique_visitors', nullif(array_to_string(array(select x from unnest(array['analytics_unique_tracking']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (3,'202610030003_unique_visitors', nullif(array_to_string(array(select x from unnest(array['analytics_events.period_visitor_hash']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (3,'202610030003_unique_visitors', nullif(array_to_string(array(select x from unnest(array['analytics_period_visitors']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (4,'202610030004_account_forks', nullif(array_to_string(array(select x from unnest(array['fork_sync_state','user_forks']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (4,'202610030004_account_forks', nullif(array_to_string(array(select x from unnest(array['reposhelf_begin_fork_sync','reposhelf_save_verified_fork']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (4,'202610030004_account_forks', nullif(array_to_string(array(select x from unnest(array['forks_owner_read','forks_state_owner_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (5,'202610030005_bookmarks_and_legal', nullif(array_to_string(array(select x from unnest(array['legal_acceptances']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (5,'202610030005_bookmarks_and_legal', nullif(array_to_string(array(select x from unnest(array['reposhelf_accept_legal','reposhelf_save_bookmark']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (5,'202610030005_bookmarks_and_legal', nullif(array_to_string(array(select x from unnest(array['user_likes.project_snapshot']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (5,'202610030005_bookmarks_and_legal', nullif(array_to_string(array(select x from unnest(array['legal_owner_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (6,'202610030006_promotions', nullif(array_to_string(array(select x from unnest(array['promotion_events','promotions']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (6,'202610030006_promotions', nullif(array_to_string(array(select x from unnest(array['reposhelf_promotion_write']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (6,'202610030006_promotions', nullif(array_to_string(array(select x from unnest(array['promotion_event_read','promotion_owner_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (6,'202610030006_promotions', nullif(array_to_string(array(select x from unnest(array['promotions_one_open_repo','promotions_owner']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (7,'202610030007_repository_submissions', nullif(array_to_string(array(select x from unnest(array['repository_submissions']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (7,'202610030007_repository_submissions', nullif(array_to_string(array(select x from unnest(array['reposhelf_claim_submissions','reposhelf_finish_submission','reposhelf_submit_repository']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (7,'202610030007_repository_submissions', nullif(array_to_string(array(select x from unnest(array['submission_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (7,'202610030007_repository_submissions', nullif(array_to_string(array(select x from unnest(array['repository_submissions_due']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (8,'202610040008_editorial_discovery_qa', nullif(array_to_string(array(select x from unnest(array['editorial_ribbons.builtin_key']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (8,'202610040008_editorial_discovery_qa', nullif(array_to_string(array(select x from unnest(array['editorial_builtin_key']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (8,'202610040008_editorial_discovery_qa', case when coalesce(exists(select 1 from cons where conname='editorial_ribbons_mode_check'),false) then null else 'constraint editorial_ribbons_mode_check' end, null),
  (8,'202610040008_editorial_discovery_qa', case when coalesce((select count(*) from public.editorial_ribbons where builtin_key in ('hero','picks','community'))=3,false) then null else 'built-in ribbons seeded (hero, picks, community)' end, null),
  (9,'202610040009_discovery_history', nullif(array_to_string(array(select x from unnest(array['user_discovery_settings','user_project_history']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (9,'202610040009_discovery_history', nullif(array_to_string(array(select x from unnest(array['reposhelf_clear_project_history','reposhelf_discovery_settings','reposhelf_remember_project']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (9,'202610040009_discovery_history', nullif(array_to_string(array(select x from unnest(array['discovery_settings_owner_read','project_history_owner_read']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (9,'202610040009_discovery_history', nullif(array_to_string(array(select x from unnest(array['user_project_history_recent']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (10,'202610040010_launch_quality_moderation_analytics', nullif(array_to_string(array(select x from unnest(array['analytics_launch_tracking','listing_controls','listing_moderation_audit','listing_reports']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (10,'202610040010_launch_quality_moderation_analytics', nullif(array_to_string(array(select x from unnest(array['reposhelf_launch_analytics','reposhelf_moderate_listing','reposhelf_public_listing_controls','reposhelf_report_listing','reposhelf_review_report']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (10,'202610040010_launch_quality_moderation_analytics', nullif(array_to_string(array(select x from unnest(array['analytics_events.shelf']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (10,'202610040010_launch_quality_moderation_analytics', nullif(array_to_string(array(select x from unnest(array['controls_admin','moderation_audit_admin','reports_admin']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (10,'202610040010_launch_quality_moderation_analytics', nullif(array_to_string(array(select x from unnest(array['listing_controls_case_id','listing_reports_inbox']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (10,'202610040010_launch_quality_moderation_analytics', case when coalesce(exists(select 1 from cons where conname='analytics_events_kind_check'),false) then null else 'constraint analytics_events_kind_check' end, null),
  (11,'202610040011_account_data_controls', nullif(array_to_string(array(select x from unnest(array['reposhelf_account_data_ready','reposhelf_account_deletion_status','reposhelf_export_account','reposhelf_guard_account_deletion']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (11,'202610040011_account_data_controls', case when coalesce(exists(select 1 from pg_trigger where tgname='reposhelf_guard_account_deletion' and not tgisinternal),false) then null else 'deletion guard trigger on auth.users' end, null),
  (11,'202610040011_account_data_controls', case when coalesce(exists(select 1 from cons where conname='promotions_user_id_fkey'),false) then null else 'constraint promotions_user_id_fkey' end, null),
  (12,'202610050012_reposhelf_popularity', nullif(array_to_string(array(select x from unnest(array['reposhelf_listing_popularity']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (12,'202610050012_reposhelf_popularity', nullif(array_to_string(array(select x from unnest(array['analytics_listing_popularity']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (12,'202610050012_reposhelf_popularity', case when coalesce(exists(select 1 from cons where conname='editorial_ribbons_mode_check' and def like '%reposhelf%'),false) then null else 'constraint editorial_ribbons_mode_check (contains reposhelf)' end, null),
  (13,'202610050013_capture_providers', nullif(array_to_string(array(select x from unnest(array['capture_settings','capture_usage']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (13,'202610050013_capture_providers', nullif(array_to_string(array(select x from unnest(array['reposhelf_approve_preview','reposhelf_capture_reserve','reposhelf_capture_settings']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (13,'202610050013_capture_providers', nullif(array_to_string(array(select x from unnest(array['listing_controls.approved_preview']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (13,'202610050013_capture_providers', nullif(array_to_string(array(select x from unnest(array['capture_settings_admin','capture_usage_admin']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (14,'202610060014_subject_taxonomy', case when coalesce((select count(*) from public.editorial_ribbons where builtin_key = any(array['category:architecture-building-design','category:games-game-development','category:animation-motion','category:simulation-physics','category:crypto-blockchain','category:food-cooking','category:automation-workflows']))=7,false) then null else 'subject shelves seeded (7 rows; deleting one in the admin shows false)' end, null),
  (15,'202610060015_expanded_categories', case when coalesce((select count(*) from public.editorial_ribbons where builtin_key = any(array['category:architecture-building-design','category:games-game-development','category:animation-motion','category:simulation-physics','category:crypto-blockchain','category:food-cooking','category:automation-workflows','category:home-automation','category:maps-geospatial','category:photography','category:health-fitness','category:android','category:apple','category:mobile','category:streaming','category:fashion','category:science','category:kids','category:automotive','category:travel']))=20,false) then null else 'category shelves seeded (20 rows; deleting one in the admin shows false)' end, null),
  (16,'202610060016_legal_version_2', case when coalesce(exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname='reposhelf_accept_legal' and prosrc like '%2026-10-06-v2%'),false) then null else 'reposhelf_accept_legal accepts 2026-10-06-v2' end, null),
  (17,'202610060017_mcp_gate', nullif(array_to_string(array(select x from unnest(array['mcp_rate_limits','mcp_usage_daily']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (17,'202610060017_mcp_gate', nullif(array_to_string(array(select x from unnest(array['reposhelf_mcp_gate','reposhelf_mcp_usage']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (18,'202610060018_more_subjects', case when coalesce((select count(*) from public.editorial_ribbons where builtin_key = any(array['category:mcp-servers-agents','category:image-audio-video-ai','category:chatbots-assistants','category:templates-ui-components','category:portfolios-personal-sites','category:browser-extensions-pwas','category:maths-algorithms','category:data-dashboards','category:3d-graphics','category:music-audio','category:writing-documents','category:self-hosted-apps','category:privacy-security']))=13,false) then null else 'subject shelves seeded (13 rows; deleting one in the admin shows false)' end, null),
  (19,'202610060019_merge_accounts', nullif(array_to_string(array(select x from unnest(array['reposhelf_merge_accounts','reposhelf_merge_check']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
