  (32,'202610110031_prompt_analytics', nullif(array_to_string(array(select x from unnest(array['reposhelf_admin_prompts','reposhelf_ingest_prompt_events']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
