  (41,'202610160035_boards', nullif(array_to_string(array(select x from unnest(array['reposhelf_boards_list','reposhelf_board_get','reposhelf_board_save','reposhelf_board_delete','reposhelf_board_item']) x where x <> all(coalesce((select a from fns),'{}'))),', '),''), 'functions'),
  (41,'202610160035_boards', nullif(array_to_string(array(select x from unnest(array['boards_owner_name','board_items_project']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (41,'202610160035_boards', case when coalesce((select count(*) from pg_class where oid in(to_regclass('public.boards'),to_regclass('public.board_items')) and relrowsecurity)=2,false) then null else 'row-level security on boards and board_items' end, null),
  (41,'202610160035_boards', case when coalesce(to_regclass('public.boards') is not null and not has_table_privilege('authenticated',to_regclass('public.boards'),'select') and not has_table_privilege('authenticated',to_regclass('public.board_items'),'select') and not has_function_privilege('authenticated',to_regprocedure('public.reposhelf_boards_list(uuid)'),'execute'),false) then null else 'boards are server-only (members cannot read tables or call functions)' end, null),
  (41,'202610160035_boards', case when coalesce(exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname='reposhelf_export_account' and prosrc like '%boards%'),false) then null else 'account export includes boards' end, null),
  (42,'202610170036_text_prompts', nullif(array_to_string(array(select x from unnest(array['ss_prompts.kind']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (42,'202610170036_text_prompts', case when coalesce(exists(select 1 from pg_constraint where conrelid=to_regclass('public.ss_prompts') and pg_get_constraintdef(oid) like '%kind%page%text%'),false) then null else 'constraint: kind must be page or text' end, null),
  (42,'202610170036_text_prompts', case when coalesce((select count(*) from public.ss_prompts s where s.source='siteshelf' and s.source_id='motion-film-director' and to_jsonb(s)->>'kind'='text')=1,false) then null else 'Motion film director listing (deleting it in the admin shows false)' end, null),
  (43,'202610170037_more_fill_in_prompts', case when coalesce((select count(*) from public.ss_prompts s where s.source='siteshelf' and s.source_id in('landing-page-builder','app-from-spec','brand-identity-kit','social-content-engine','explainer-video-script','market-research-brief') and to_jsonb(s)->>'kind'='text')=6,false) then null else 'the six fill-in prompt listings (deleting one in the admin shows false)' end, null),
  (43,'202610170037_more_fill_in_prompts', case when coalesce((select count(*) from public.ss_prompts s where s.source='siteshelf' and s.source_id in('landing-page-builder','app-from-spec') and s.prompt like '%<board>%')=2,false) then null else 'reference board block in the Landing page builder and App builder (shows false if you have edited those prompts)' end, null),
  (44,'202610180038_prompt_edits_and_deletions', nullif(array_to_string(array(select x from unnest(array['ss_prompts.edited_fields']) x where x <> all(coalesce((select a from cols),'{}'))),', '),''), 'columns'),
  (44,'202610180038_prompt_edits_and_deletions', nullif(array_to_string(array(select x from unnest(array['ss_prompt_tombstones']) x where x <> all(coalesce((select a from tbls),'{}'))),', '),''), 'tables'),
  (44,'202610180038_prompt_edits_and_deletions', case when coalesce(not has_table_privilege('anon',to_regclass('public.ss_prompt_tombstones'),'select') and not has_table_privilege('authenticated',to_regclass('public.ss_prompt_tombstones'),'select'),false) then null else 'the tombstones table is server-only (no browser grants)' end, null),
  (45,'202610180039_advisor_fixes', nullif(array_to_string(array(select x from unnest(array['likes_owner','promotion_owner_read','promotion_event_read','submission_read','ribbons_public_anon','ribbons_read_members','ribbons_admin_insert','ribbons_admin_update','ribbons_admin_delete','settings_admin_insert','settings_admin_update','settings_admin_delete']) x where x <> all(coalesce((select a from pols),'{}'))),', '),''), 'policies'),
  (45,'202610180039_advisor_fixes', nullif(array_to_string(array(select x from unnest(array['admin_role_changes_actor','admin_role_changes_target','board_items_board_user','listing_moderation_audit_actor','listing_reports_reporter','promotion_events_promotion','promotions_reviewed_by','viewer_site_prefs_updated_by']) x where x <> all(coalesce((select a from idxs),'{}'))),', '),''), 'indexes'),
  (46,'202610180040_export_and_merge_counts', case when coalesce(pg_get_functiondef(to_regprocedure('public.reposhelf_export_account()')) like '%connectorKeys%' and pg_get_functiondef(to_regprocedure('public.reposhelf_merge_check(uuid,uuid)')) like '%n_keys%',false) then null else 'the account export and merge preview functions are the new versions' end, null),
  (47,'202610180041_legal_version_5', case when coalesce(exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname='reposhelf_accept_legal' and prosrc like '%2026-10-18-v5%'),false) then null else 'reposhelf_accept_legal accepts 2026-10-18-v5' end, null)
 ),
 findings as (
  select ord, migration, case when problem is null then null when kind is null then problem else 'missing '||kind||': '||problem end as problem from checks),
 per as (
  select ord, migration,
         bool_and(problem is null) as applied,
         count(*) filter (where problem is null)::int as passed,
         count(*)::int as total,
         string_agg(problem, E'\n') filter (where problem is not null) as missing
  from findings group by ord, migration)
select migration, applied, passed||' / '||total as checks_passed, missing
from (
  select ord, migration, applied, passed, total, missing from per
  union all
  select 9999, 'ALL MIGRATIONS', bool_and(applied), sum(passed)::int, sum(total)::int,
         case when bool_and(applied) then 'Everything is in place.'
              else count(*) filter (where not applied)||' migration(s) need attention - see the rows above.' end
  from per) r
order by ord;
